#!/usr/bin/env python3
"""Minimal agentic loop using the Anthropic API with a bash tool gated by human confirmation.

Usage:
    export ANTHROPIC_API_KEY=sk-ant-...
    python agent-loop.py "list the python files in this directory"

Requires: pip install anthropic
"""

import os
import sys
import subprocess

from anthropic import Anthropic

MODEL = "claude-sonnet-4-6"
MAX_TOKENS = 4096
COMMAND_TIMEOUT_SECONDS = 120

SYSTEM_PROMPT = (
    "You are a helpful coding assistant with access to a `run_bash` tool that executes "
    "shell commands on the user's local machine. Each command requires the user's "
    "explicit confirmation, so prefer small, focused commands and explain your intent. "
    "If the user declines a command, do not retry the same command — ask what they want "
    "instead. Keep responses concise."
)

TOOLS = [
    {
        "name": "run_bash",
        "description": (
            "Execute a single bash command on the user's machine and return its "
            "stdout, stderr, and exit code. The user must approve each command before "
            "it runs; if they decline, the tool result will say so and you should "
            "adjust your plan rather than retrying."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "command": {
                    "type": "string",
                    "description": "The bash command to execute.",
                },
            },
            "required": ["command"],
        },
    }
]


def confirm(command: str) -> bool:
    print("\n\033[33m--- Proposed command ---\033[0m")
    print(command)
    print("\033[33m------------------------\033[0m")
    try:
        answer = input("Run this command? [y/N]: ").strip().lower()
    except EOFError:
        return False
    return answer in ("y", "yes")


def run_bash(command: str) -> tuple[str, bool]:
    """Returns (formatted_result, is_error)."""
    if not confirm(command):
        return ("User declined to run this command.", True)
    try:
        proc = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=COMMAND_TIMEOUT_SECONDS,
        )
    except subprocess.TimeoutExpired:
        return (f"Command timed out after {COMMAND_TIMEOUT_SECONDS}s.", True)

    parts = [f"exit_code: {proc.returncode}"]
    if proc.stdout:
        parts.append(f"stdout:\n{proc.stdout}")
    if proc.stderr:
        parts.append(f"stderr:\n{proc.stderr}")
    return ("\n".join(parts), False)


def agent_turn(client: Anthropic, messages: list) -> str:
    """Drive the model until it stops requesting tools. Returns the final text reply."""
    while True:
        response = client.messages.create(
            model=MODEL,
            max_tokens=MAX_TOKENS,
            system=[
                {
                    "type": "text",
                    "text": SYSTEM_PROMPT,
                    "cache_control": {"type": "ephemeral"},
                }
            ],
            tools=TOOLS,
            messages=messages,
        )
        messages.append({"role": "assistant", "content": response.content})

        if response.stop_reason != "tool_use":
            return "".join(b.text for b in response.content if b.type == "text")

        tool_results = []
        for block in response.content:
            if block.type != "tool_use":
                continue
            if block.name == "run_bash":
                content, is_error = run_bash(block.input["command"])
            else:
                content, is_error = f"Unknown tool: {block.name}", True
            tool_results.append(
                {
                    "type": "tool_result",
                    "tool_use_id": block.id,
                    "content": content,
                    "is_error": is_error,
                }
            )
        messages.append({"role": "user", "content": tool_results})


def main() -> int:
    if not os.environ.get("ANTHROPIC_API_KEY"):
        print("error: ANTHROPIC_API_KEY is not set", file=sys.stderr)
        return 1

    client = Anthropic()
    messages: list = []

    initial = " ".join(sys.argv[1:]).strip()
    if initial:
        messages.append({"role": "user", "content": initial})
        reply = agent_turn(client, messages)
        if reply:
            print(f"\n\033[36mAssistant:\033[0m {reply}\n")

    while True:
        try:
            user_input = input("\033[32mYou:\033[0m ").strip()
        except (EOFError, KeyboardInterrupt):
            print()
            return 0
        if not user_input:
            continue
        if user_input.lower() in ("exit", "quit"):
            return 0
        messages.append({"role": "user", "content": user_input})
        reply = agent_turn(client, messages)
        if reply:
            print(f"\n\033[36mAssistant:\033[0m {reply}\n")


if __name__ == "__main__":
    sys.exit(main())

